// Un producto destacado por categoría, para el bloque "Lo más recomendado"
// que aparece en todas las páginas (ver featuredProductsSection en lib.js).
// Se reutilizan los datos ya cargados en GUIDES para no duplicar imagen/precio.
function pickFeatured(guideSlug, asin) {
  const g = GUIDES.find((x) => x.slug === guideSlug);
  const p = g.products.find((x) => x.asin === asin);
  return { ...p, category: g.slug, categoryTitle: g.title };
}

const FEATURED = [
  pickFeatured("camaras-de-conduccion-dash-cams", "B0C33RDGY8"),
  pickFeatured("cargadores-de-coche-usb", "B0GJCP9FG2"),
  pickFeatured("soportes-de-movil-para-coche", "B0D2Q5M35Y"),
  pickFeatured("cables-y-arrancadores-de-bateria", "B0FB86S2ZC"),
  pickFeatured("organizadores-de-maletero", "B0DNQ5V1YH"),
  pickFeatured("aspiradores-portatiles-para-coche", "B0GY4BVN2Y"),
  pickFeatured("alfombrillas-y-protectores-de-suelo-para-coche", "B0GN959NR6"),
  pickFeatured("luces-y-accesorios-de-emergencia-para-coche", "B0FXMTMGS8"),
  pickFeatured("fundas-y-protectores-de-asiento", "B07H3SDKH7"),
  pickFeatured("purificadores-y-ambientadores-de-coche", "B09GG3RX93"),
];

// Ampliación (ver extra.js): productos top nuevos y artículos de blog.
const EXTRA = require("./extra");
for (const g of GUIDES) g.products.push(...(EXTRA.products[g.slug] || []));
for (const a of EXTRA.articles) {
  const g = GUIDES.find((x) => x.slug === a.guide);
  ARTICLES.push({ ...a, img: a.img || (g && g.img) });
}

module.exports = { GUIDES, ARTICLES, FEATURED };
